// front/components/MovieCard.tsx
"use client";

import { useState } from "react";
import { Movie } from "@/types/movie";
import { updateMovie } from "@/lib/api";

export default function MovieCard({
  movie,
  onWatched,
}: {
  movie: Movie;
  onWatched: (message: string) => void;
}) {
  const friendTags =
    typeof movie.friends_recommended === "string"
      ? Array.from(
          new Set(
            movie.friends_recommended
              .split(",")
              .map((t) => t.trim())
              .filter(Boolean),
          ),
        )
      : [];

  const myTags = movie.my_tags
    ? Array.from(
        new Set(
          movie.my_tags
            .split(",")
            .map((t) => t.trim())
            .filter(Boolean),
        ),
      )
    : [];

  const [tagInput, setTagInput] = useState("");
  const [saving, setSaving] = useState(false);
  const [rating, setRating] = useState<number>(movie.rating ?? 0);

  const params =
    typeof window !== "undefined"
      ? new URLSearchParams(window.location.search)
      : null;

  const activeFriend = params?.get("friends_recommended");
  const activeTag = params?.get("my_tag");

  return (
    <div className="flex gap-4 rounded-xl border border-zinc-800 bg-zinc-950 p-4">
      {/* Poster */}
      {movie.image_url && (
        <img
          src={movie.image_url}
          alt={movie.title}
          className="h-auto w-[90px] flex-shrink-0 rounded-lg"
        />
      )}

      {/* Content */}
      <div className="flex flex-1 flex-col gap-3">
        {/* Title */}
        <div>
          <h3 className="text-base font-medium text-zinc-100">
            {movie.title ?? movie.imdb_id}
            {movie.year && (
              <span className="ml-2 text-sm font-normal text-zinc-500">
                ({movie.year})
              </span>
            )}
          </h3>

          <div
            className={`mt-1 text-xs ${
              movie.watched ? "text-emerald-400/70" : "text-amber-400/70"
            }`}
          >
            ● {movie.watched ? "Watched" : "Not watched"}
          </div>
        </div>

        {/* Watched content */}
        {movie.watched && (
          <div className="grid gap-4 md:grid-cols-3">
            {/* Friends */}
            <div>
              <div className="mb-1 text-xs text-zinc-500">Recommended by</div>
              <div className="flex flex-wrap gap-2">
                {friendTags.map((friend) => {
                  const isActive =
                    activeFriend?.toLowerCase() === friend.toLowerCase();

                  return (
                    <button
                      key={friend}
                      onClick={() => {
                        const p = new URLSearchParams(window.location.search);
                        isActive
                          ? p.delete("friends_recommended")
                          : p.set("friends_recommended", friend);
                        window.location.href = `/library/movies?${p.toString()}`;
                      }}
                      className={`rounded-full px-3 py-1 text-xs transition ${
                        isActive
                          ? "border border-blue-500 bg-blue-500/10 text-blue-300"
                          : "border border-zinc-700 text-zinc-300 hover:bg-zinc-800"
                      }`}
                    >
                      {friend}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Tags */}
            <div>
              <div className="mb-1 text-xs text-zinc-500">My tags</div>
              <div className="flex flex-wrap gap-2">
                {myTags.map((tag) => {
                  const isActive =
                    activeTag?.toLowerCase() === tag.toLowerCase();

                  return (
                    <button
                      key={tag}
                      onClick={() => {
                        const p = new URLSearchParams(window.location.search);
                        isActive ? p.delete("my_tag") : p.set("my_tag", tag);
                        window.location.href = `/library/movies?${p.toString()}`;
                      }}
                      className={`rounded-full px-3 py-1 text-xs transition ${
                        isActive
                          ? "border border-blue-500 bg-blue-500/10 text-blue-300"
                          : "border border-zinc-700 text-zinc-300 hover:bg-zinc-800"
                      }`}
                    >
                      #{tag}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Rating */}
            <div>
              <div className="mb-1 text-xs text-zinc-500">Rating</div>
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    onClick={async () => {
                      setRating(star);
                      const res = await updateMovie(movie.imdb_id, {
                        rating: star,
                      });
                      const data = await res.json();
                      onWatched(data.message);
                    }}
                    className={`text-lg transition ${
                      star <= rating
                        ? "text-yellow-400/80"
                        : "text-zinc-600 hover:text-zinc-400"
                    }`}
                  >
                    ★
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Unwatched */}
        {!movie.watched && (
          <div className="flex flex-col gap-2">
            <div className="text-xs text-zinc-500">
              My tags (comma-separated)
            </div>

            <input
              value={tagInput}
              onChange={(e) => setTagInput(e.target.value)}
              placeholder="e.g. action, rewatch"
              className="rounded-md border border-zinc-700 bg-zinc-900 px-3 py-2 text-sm text-zinc-100 placeholder:text-zinc-500"
            />

            <button
              type="button"
              disabled={saving}
              onClick={async () => {
                setSaving(true);

                const uniqueTags = Array.from(
                  new Set(
                    tagInput
                      .split(",")
                      .map((t) => t.trim())
                      .filter(Boolean),
                  ),
                ).join(",");

                const res = await updateMovie(movie.imdb_id, {
                  watched: true,
                  my_tags: uniqueTags,
                });

                const data = await res.json();
                onWatched(data.message);
                setSaving(false);
              }}
              className="
                w-fit
                rounded-lg
                border border-zinc-700
                bg-zinc-900
                px-4 py-2
                text-sm font-medium text-zinc-300
                hover:bg-zinc-800
                disabled:opacity-50
              "
            >
              {saving ? "Saving…" : "Mark as Watched"}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
